  $$('[data-step-count]').forEach(e=>e.textContent=`${state[e.dataset.stepCount]+1} / ${stepLimit(e.dataset.stepCount)+1}`);
  $$('[data-run]').forEach(e=>e.textContent=runningStep===e.dataset.run?'Pause':'Play');
  const r=rows.find(r=>r.id===state.sample),p=r.a,alert=p>=state.threshold;
  $('[data-action="outcome"]').textContent=state.outcome?'Hide observed outcome':'Reveal observed outcome';
  $('[data-render="probability-card"]').innerHTML=`<p class="step-label">MODEL A · ${r.id}</p><h3>Estimated probability of a delay</h3><div class="big-number">${pct(p)}</div><div class="bars"><div class="bar"><span style="width:${p*100}%"></span></div></div><div class="stat-row"><div><strong>${state.threshold.toFixed(2)}</strong><span>decision threshold</span></div><div><strong>${alert?'Alert':'No alert'}</strong><span>${p.toFixed(2)} ${alert?'≥':'<'} ${state.threshold.toFixed(2)}</span></div></div><p class="note">${state.outcome?`Observed later: <strong>${r.y?'late':'on time'}</strong>. This is a ${defs[r.y?(alert?'tp':'fn'):(alert?'fp':'tn')][0]}.`:'The observed outcome is hidden until you reveal it.'}</p>`;
  $('[data-render="baseline-model"]').innerHTML=`<p class="step-label">MODEL ${state.model.toUpperCase()} · THRESHOLD ${state.threshold.toFixed(2)}</p><strong class="big-number">${pct(c.accuracy)}</strong><p>accuracy</p><p>${c.tp} of 10 delays found.<br>${c.alerts} deliveries reviewed.</p>`;
  $('[data-render="matrix-totals"]').innerHTML=`<h3>Which group are we counting?</h3><div class="total-row">All deliveries <strong>${c.tp} + ${c.fn} + ${c.fp} + ${c.tn} = 100</strong></div><div class="total-row">Actual delays <strong>TP + FN = ${c.positive}</strong></div><div class="total-row">Alerts issued <strong>TP + FP = ${c.alerts}</strong></div><p class="small">Change the threshold. Only the alert total can change; there are still 100 deliveries and 10 actual delays.</p>`;
  $('[data-render="specificity-detail"]').innerHTML=state.specificityMetric==='fpr'?detail('False positive rate','FP / (FP + TN)',c.fp,c.fp+c.tn,'Of the on-time deliveries, how many triggered a false alarm?'):detail('Specificity','TN / (TN + FP)',c.tn,c.tn+c.fp,'Of the on-time deliveries, how many were left unflagged?');
  const pop=M.population(+state.prevalence,.6,.02),total=pop.alerts;
  $('[data-depth-chart="population"]').innerHTML=`<text class="axis-title" x="85" y="48">Expected alerts in 10,000 deliveries</text><rect x="85" y="95" width="${535*pop.tp/total}" height="72" fill="var(--mint)"/><rect x="${85+535*pop.tp/total}" y="95" width="${535*pop.fp/total}" height="72" fill="var(--amber)"/><text x="85" y="210">${pop.tp.toFixed(0)} correct alerts · ${pop.fp.toFixed(0)} false alarms</text><text x="85" y="260">Precision = ${pop.tp.toFixed(0)} / ${total.toFixed(0)}</text><text class="population-result" x="85" y="330">${pct(pop.precision)}</text>`;
  $('[data-render="population-numbers"]').innerHTML=`<div class="legend"><span><i></i>Correct alert</span><span><i class="late"></i>False alarm</span></div><h3>${pct(pop.precision)} of alerts are correct.</h3><p>${(10000*state.prevalence).toFixed(0)} actual delays.<br>${pop.fn.toFixed(0)} missed delays.<br>${total.toFixed(0)} deliveries to review.</p>`;
  $('[data-render="roc-limit-table"]').innerHTML=`<table class="reading-table"><thead><tr><th>10,000 deliveries</th><th>1% late</th><th>10% late</th></tr></thead><tbody>${[['Actual delays',100,1000],['Delays found (TP)',60,600],['False alarms (FP)',198,180],['Total reviews',258,780],['Recall','60%','60%'],['FPR','2%','2%'],['Precision',pct(M.population(.01,.6,.02).precision),pct(M.population(.1,.6,.02).precision)]].map(row=>`<tr><th>${row[0]}</th><td>${row[1]}</td><td>${row[2]}</td></tr>`).join('')}</tbody></table>`;
  const cap=M.capacity(rows,+state.capacity,state.model),queue=[...rows].sort((a,b)=>b[state.model]-a[state.model]);
